const fullText = $input.first().json.text || '';
const totalLength = fullText.length;

// 1. Tìm từ khóa Mục lục
const tocRegex = /(?:table\s+of\s+contents|mục\s+lục|^contents$)/i;
const tocMatch = fullText.match(tocRegex);

if (!tocMatch) {
  // Không tìm thấy từ khóa -> Mặc định cắt 15,000 ký tự đầu sách
  return [{
    json: {
      tocText: fullText.substring(0, 15000).trim(),
      method: "Fallback (No TOC Keyword Found)",
      isBackToc: false
    }
  }];
}

const tocStartIndex = tocMatch.index;

// 2. Kiểm tra vị trí: Mục lục nằm ở nửa đầu hay nửa cuối sách?
const isBackToc = tocStartIndex > (totalLength * 0.5);

let exactTocText = '';
let method = '';

if (isBackToc) {
  // === TRƯỜNG HỢP A: MỤC LỤC Ở CUỐI SÁCH ===
  // Chỉ cần lấy từ vị trí "Table of Contents" kéo dài 15,000 ký tự về sau (hoặc đến hết sách)
  exactTocText = fullText.substring(tocStartIndex, tocStartIndex + 15000);
  method = "Back TOC (Extracted from second half of PDF)";

} else {
  // === TRƯỜNG HỢP B: MỤC LỤC Ở ĐẦU SÁCH (Phổ biến) ===
  const textFromToc = fullText.substring(tocStartIndex);
  const startKeywords = [
    'Introduction', 
    'Chapter 1', 
    'Chương 1', 
    'Lời nói đầu', 
    'PREFACE', 
    '1. Introduction'
  ];

  let tocEndIndex = -1;
  let matchedKeyword = '';

  for (const kw of startKeywords) {
    const regex = new RegExp(kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    const matches = [...textFromToc.matchAll(regex)];

    // Nếu từ khóa xuất hiện từ 2 lần trở lên
    if (matches.length >= 2) {
      tocEndIndex = tocStartIndex + matches[1].index;
      matchedKeyword = kw;
      break;
    }
  }

  if (tocEndIndex !== -1) {
    exactTocText = fullText.substring(tocStartIndex, tocEndIndex);
    method = `Front TOC Exact Cut (End keyword: ${matchedKeyword})`;
  } else {
    exactTocText = fullText.substring(tocStartIndex, tocStartIndex + 12000);
    method = "Front TOC Safe Cut";
  }
}

return [{
  json: {
    tocText: exactTocText.trim(),
    method: method,
    isBackToc: isBackToc,
    length: exactTocText.length
  }
}];

// 1. Lấy toàn bộ văn bản PDF từ node trước
let fullText = $input.first().json.text || '';

if (!fullText) {
  return [{ json: { error: "Không tìm thấy biến 'text' chứa nội dung PDF từ node trước." } }];
}

// Chuẩn hóa xuống dòng
fullText = fullText.replace(/\\n/g, '\n').replace(/\r/g, '');

// 2. Cấu hình thông số Chunking (Tối ưu cho Context 8k)
const CHUNK_SIZE = 12000; // ~3,000 tokens
const OVERLAP = 500;     // ~125 tokens gối đầu để không bị đứt đoạn ý

const items = [];
let start = 0;
let chunkIndex = 1;

// 3. Thuật toán cắt văn bản thông minh (Smart Breaking)
while (start < fullText.length) {
  let end = start + CHUNK_SIZE;

  if (end >= fullText.length) {
    end = fullText.length;
  } else {
    // Tìm điểm ngắt tự nhiên (đoạn văn \n\n, xuống dòng \n, hoặc cuối câu . )
    // Tránh việc bị xén ngang một từ hoặc một câu văn
    const slice = fullText.substring(start, end);
    let breakPoint = slice.lastIndexOf('\n\n');

    if (breakPoint === -1 || breakPoint < CHUNK_SIZE * 0.7) {
      breakPoint = slice.lastIndexOf('\n');
    }
    if (breakPoint === -1 || breakPoint < CHUNK_SIZE * 0.7) {
      breakPoint = slice.lastIndexOf('. ');
    }
    if (breakPoint !== -1 && breakPoint > CHUNK_SIZE * 0.5) {
      end = start + breakPoint + 1;
    }
  }

  const chunkContent = fullText.substring(start, end).trim();

  if (chunkContent.length > 0) {
    items.push({
      json: {
        chunkIndex: chunkIndex,
        content: chunkContent,
        charLength: chunkContent.length
      }
    });
    chunkIndex++;
  }

  if (end >= fullText.length) break;
  // Dịch chuyển vị trí bắt đầu cho chunk sau (có tính gối đầu OVERLAP)
  start = end - OVERLAP;
}

// 4. Gán tổng số chunk vào từng item để dễ theo dõi
const totalChunks = items.length;
return items.map(item => {
  item.json.totalChunks = totalChunks;
  return item;
});

// Lấy dữ liệu đã gom từ node Aggregate
const rawData = $input.first().json.output;

// Chuẩn hóa thành chuỗi văn bản duy nhất
const combinedText = Array.isArray(rawData) ? rawData.join("\n\n---\n\n") : String(rawData);

const charCount = combinedText.length;
const wordCount = combinedText.trim().split(/\s+/).length;

// Ước tính số token (mỗi token ~ 2.8 ký tự tiếng Việt)
const estimatedTokens = Math.ceil(charCount / 2.8);

// Kiểm tra ngưỡng an toàn cho Context Window 8k (cho phép tối đa 5000 tokens input)
const isSafe = estimatedTokens <= 5000;

return [{
  json: {
    charCount: charCount,
    wordCount: wordCount,
    estimatedTokens: estimatedTokens,
    isSafeFor8kContext: isSafe,
    status: isSafe ? "✅ AN TOÀN: Đưa sang Node LLM cuối" : "⚠️ CẢNH BÁO: Quá dài cho 8k context!",
    text: combinedText
  }
}];

// 1. Lấy toàn bộ dữ liệu từ Node LLM Metadata
const llmItem = $('LLM Metadata').first().json;

// Tìm chuỗi dữ liệu trong các trường phổ biến của n8n AI Nodes
let rawLlOutput = llmItem.output ?? llmItem.text ?? llmItem.response ?? llmItem.message?.content ?? llmItem;

// Giá trị mặc định
let metadata = { 
  description: "Bản tổng hợp chi tiết từ cuốn sách.", 
  tags: ["book-summary", "knowledge-base"] 
};

let debugStatus = "OK";

if (typeof rawLlOutput === 'object' && rawLlOutput !== null) {
  // Trường hợp n8n đã tự động parse thành Object từ trước
  if (rawLlOutput.description) metadata.description = rawLlOutput.description;
  if (Array.isArray(rawLlOutput.tags)) metadata.tags = rawLlOutput.tags;
  debugStatus = "Thành công (Đã là Object)";
} else if (typeof rawLlOutput === 'string') {
  // Trích xuất chính xác đoạn chuỗi nằm giữa cặp dấu { và }
  const jsonMatch = rawLlOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.description) metadata.description = parsed.description;
      if (Array.isArray(parsed.tags)) metadata.tags = parsed.tags;
      debugStatus = "Thành công (Parse từ JSON String)";
    } catch (e) {
      debugStatus = `Lỗi JSON.parse: ${e.message}`;
    }
  } else {
    debugStatus = "Lỗi: LLM không trả về chuỗi có cấu trúc dạng { ... }";
  }
} else {
  debugStatus = "Lỗi: Dữ liệu từ Node LLM Metadata bị rỗng";
}

// Chuyển mảng tags thành dạng chuẩn YAML
const yamlTags = JSON.stringify(metadata.tags);

// 2. Lấy danh sách tóm tắt từ Node Aggregate
const aggregateJson = $('Aggregate').first().json;
const rawSummaries = aggregateJson.text || aggregateJson.content || $input.first().json.text || [];
const summaries = Array.isArray(rawSummaries) ? rawSummaries : [rawSummaries];

// 3. Lấy Tiêu đề sách từ Node Read PDF
const bookTitle = $('Read PDF').first().json.Title || $('Read PDF').first().json.info?.Title || $('Read/Write Files from Disk').first().json.fileName || "Game Project Completed";

// Dọn dẹp tên file an toàn
const safeFileName = bookTitle.replace(/[/\\?%*:|"<>]/g, '_');
const fileName = safeFileName.endsWith('.md') ? safeFileName : `${safeFileName}.md`;

// 4. Tạo YAML Frontmatter
const yamlHeader = `---
title: "${bookTitle}"
description: "${metadata.description}"
tags: ${yamlTags}
date: "${new Date().toISOString().split('T')[0]}"
language: vi
---

`;

// 5. Ghép toàn bộ nội dung Markdown
const fullMarkdown = yamlHeader + summaries.map((chunkText, idx) => `## Phần ${idx + 1}\n\n${chunkText}`).join('\n\n---\n\n');

return [{
  json: {
    fileName: fileName,
    content: fullMarkdown,
    totalChunksProcessed: summaries.length,
    // --- Bổ sung 2 thuộc tính để kiểm tra trực tiếp trên UI của n8n ---
    debugStatus: debugStatus,
    debugRawLLMOutput: rawLlOutput
  }
}];
